-- ==========================================================
-- SAMPLE DATA 2/2 : a few events to try the app with
--
-- Only for a database that has NO events yet (otherwise it inserts nothing).
-- Run it in the MAIN database (myv_myTickets), after 01_venues_and_seats.sql.
--
-- Dates are relative to today, so the list always has shows that are on sale,
-- shows whose sales open later, and one show that is already over.
-- The artists are made up. event_id (EV01, EV02, ...) is generated by trg_event_bi_id.
-- ==========================================================
SET NAMES utf8mb4;   -- this file contains Vietnamese text
USE myv_myTickets;

SET @fresh := (SELECT COUNT(*) = 0 FROM event) AND (SELECT COUNT(*) FROM venue) >= 5;
SET @today := CURRENT_DATE();

INSERT INTO event (event_id, venue_id, event_name, artist, sale_time, start_time, standing_capacity)
SELECT NULL, e.venue_id, e.event_name, e.artist, e.sale_time, e.start_time, e.standing_capacity
  FROM (
    -- on sale now
              SELECT 1 AS n, 'VE01' AS venue_id, 'Midnight Velvet Sessions' AS event_name, 'The Low Tones' AS artist,
                     @today - INTERVAL 10 DAY + INTERVAL 10 HOUR AS sale_time,
                     @today + INTERVAL  6 DAY + INTERVAL 21 HOUR AS start_time, 250 AS standing_capacity
    UNION ALL SELECT 2, 'VE02', 'Đêm Hội An: Paper Lanterns Unplugged', 'Mộc Lan',
                     @today - INTERVAL  7 DAY + INTERVAL 10 HOUR,
                     @today + INTERVAL 12 DAY + INTERVAL 20 HOUR, 0
    UNION ALL SELECT 3, 'VE04', 'Neon Tide: Afterglow Tour', 'Neon Tide',
                     @today - INTERVAL  3 DAY + INTERVAL 12 HOUR,
                     @today + INTERVAL 23 DAY + INTERVAL 19 HOUR, 600
    UNION ALL SELECT 4, 'VE03', 'Starlight Symphony: Film Scores Live', 'Saigon Pops Orchestra',
                     @today - INTERVAL  1 DAY + INTERVAL  9 HOUR,
                     @today + INTERVAL 37 DAY + INTERVAL 19 HOUR + INTERVAL 30 MINUTE, 0
    -- sales open later
    UNION ALL SELECT 5, 'VE05', 'Skyline Fest', 'Neon Tide, Mộc Lan and friends',
                     @today + INTERVAL  3 DAY + INTERVAL 10 HOUR,
                     @today + INTERVAL 60 DAY + INTERVAL 16 HOUR, 1500
    UNION ALL SELECT 6, 'VE02', 'Hà Nội Mùa Thu Acoustic', 'Thu Hà',
                     @today + INTERVAL 10 DAY + INTERVAL 10 HOUR,
                     @today + INTERVAL 45 DAY + INTERVAL 20 HOUR, 0
    -- already over (history)
    UNION ALL SELECT 7, 'VE01', 'Summer Rewind Party', 'DJ Khoa',
                     @today - INTERVAL 60 DAY + INTERVAL 10 HOUR,
                     @today - INTERVAL 20 DAY + INTERVAL 21 HOUR, 250
  ) e
 WHERE @fresh
 ORDER BY e.n;

SELECT event_id, venue_id, event_name, sale_time, start_time, standing_capacity FROM event ORDER BY event_id;
